"desktop" | 
/**  Web embedding. */
"web" | 
/**  App embedding. */
"app" | 
/**  Trial. */
"trial" | 
/**  Personal use only. */
"personalOnly" | 
/**  Not known. */
"unknown";

/**  List families, one page at a time (the UI list is virtualized). */
export type ListFamiliesRequest = {
	/**  One source, or all unpaused sources when absent. */
	source?: SourceId | null,
	/**  Order. */
	sort?: FamilySort,
	/**  Window. */
	page?: Page,
	/**  Order by any column of the detail list; when set, it replaces `sort`. */
	order?: FamilyOrder | null,
};

/**  Vertical metrics in font units. */
export type Metrics = {
	/**  Units per em. */
	unitsPerEm: number,
	/**  Typographic ascender. */
	ascender: number,
	/**  Typographic descender (negative). */
	descender: number,
	/**  x-height, when the font declares it. */
	xHeight: number | null,
	/**  Cap height, when the font declares it. */
	capHeight: number | null,
};

/**  Near-miss detail for a coverage filter. */
export type Missing = {
	/**  The exact characters the face lacks. */
	chars: string[],
	/**  The face carries `locl` forms for the requested language. */
	hasLocl: boolean,
};

/**
 *  Move a collection under another parent, or to another place among its
 *  siblings.
 */
export type MoveCollectionRequest = {
	/**  The collection. */
	collection: CollectionId,
	/**
	 *  The new parent; absent for the top level. The collection itself or
	 *  one of its children is `InvalidRequest`.
	 */
	parent?: CollectionId | null,
	/**  Its place among the new siblings, 0 first; past the end means last. */
	position: number,
};

/**  A named instance of a variable font, listed as a style. */
export type NamedInstance = {
	/**  Style name ("Semibold"). */
	name: string,
	/**  Its axis coordinates. */
	coordinates: AxisValue[],
};

/**  An open-source license recognized from the license text. */
export type OpenLicense = 
/**  SIL Open Font License. */
"ofl" | 
/**  Apache License 2.0. */
"apache" | 
/**  Ubuntu Font Licence. */
"ufl" | 
/**  MIT. */
"mit";

/**  What happened to one face. */
export type OutcomeStatus = 
/**  Now active (or now inactive, for a deactivation). */
{ status: "done" } | 
/**  Already in the requested state. */
{ status: "unchanged" } | 
/**  Not done because of a clash (with `KeepExisting`). */
{ status: "conflict"; 
/**  What it clashes with. */
with: ConflictWith } | 
/**  Not done: the app did not register it, or the format cannot be activated. */
{ status: "skipped"; 
/**  Why, in plain words. */
reason: string } | 
/**  The OS call failed. */
{ status: "failed"; 
/**  The error. */
error: ApiError };

/**  A window into a long list. `limit` is capped by the service (500). */
export type Page = {
	/**  Rows to skip. */
	offset: number,
	/**  Rows to return. */
	limit: number,
};

/**  One page of results and the size of the whole list. */
export type Paged<T> = {
	/**  The rows in this page. */
	items: T[],
	/**  Rows in the whole list. */
	total: number,
};

/**  The operating system the app runs on. */
export type Platform = 
/**  Windows 10 or 11. */
"windows" | 
/**  macOS. */
"macos" | 
/**  Linux. */
"linux";

/**  Activate a family, subset it and return its CSS. */
export type PrepareForWebRequest = {
	/**  The family. */
	family: FamilyId,
	/**  Subset; the full character set when absent. */
	subset?: Subset | null,
	/**  Output folder. */
	outDir: string,
};

/**  What `prepare_for_web` did. */
export type PrepareForWebResponse = {
	/**  Session activation, per face. */
	activated: ActivationOutcome[],
	/**  The export. */
	export: ExportWebResponse,
};

/**  A rendered preview. */
export type PreviewImage = {
	/**  Width in pixels. */
	width: number,
	/**  Height in pixels. */
	height: number,
	/**  PNG bytes. */
	png: number[],
};

/**  Render a line of text in one face. */
export type PreviewRequest = {
	/**  The face. */
	face: FaceId,
	/**  The text. */
	text: string,
	/**  Size in pixels (8–300). */
	sizePx: number | null,
	/**  Variation coordinates; defaults for unlisted axes. */
	variations?: AxisValue[],
	/**  Features switched on or off. */
	features?: FeatureSetting[],
	/**  Text color, CSS hex (`#1a1a1a`); black when absent. */
	foreground?: string | null,
	/**  Background color, CSS hex; transparent when absent. */
	background?: string | null,
};

/**  One entry of the Problems view. */
export type Problem = {
	/**  What kind. */
	kind: ProblemKind,
	/**  The face, when the file parsed far enough to have one. */
	face: FaceId | null,
	/**  The file. */
	path: string,
	/**  The other face or file it clashes with, for duplicates and conflicts. */
	other: string | null,
	/**  One sentence for the user. */
	message: string,
};

/**  What kind of health problem. */
export type ProblemKind = 
/**  The same file (same hash) at two paths. */
"duplicateFile" | 
/**  The same family, style and version at different paths. */
"duplicateFace" | 
/**  Truncated or missing required tables. */
"broken" | 
/**  No Unicode `cmap`. */
"noUnicodeCmap" | 
/**  Same PostScript name as a system font. */
"systemConflict" | 
/**  Same PostScript name as a font already active from another source. */
"activeConflict" | 
/**  A format the app cannot activate. */
"unsupported" | 
/**
 *  Sidecar metadata (`<source>/.fontlibrary/`) that could not be merged:
 *  another machine set a field to a different value, or the sidecar file
 *  cannot be read. Nothing is overwritten until the user decides.
 */
"sidecarConflict";

/**  A project set: fonts activated together. */
export type ProjectSet = {
	/**  Id. */
	id: SetId,
	/**  Name. */
	name: string,
	/**  The faces. */
	faces: FaceId[],
};

/**  Rename a collection. */
export type RenameCollectionRequest = {
	/**  The collection. */
	collection: CollectionId,
	/**  New name. */
	name: string,
};

/**  Why a face previews other text than the sample. */
export type SampleFallback = 
/**  Letters of a script the face covers. */
{ kind: "script"; 
/**  ISO 15924 script (`Cyrl`). */
script: string } | 
/**  Characters the face maps, for a face that covers no language. */
{ kind: "symbols" };

/**  The text one face previews. */
export type SampleText = {
	/**  The face. */
	face: FaceId,
	/**  The sample text, or text from the face's own coverage. */
	text: string,
	/**  Set when the face lacks characters of the sample and `text` is other text. */
	fallback?: SampleFallback | null,
	/**  The characters of the sample the face lacks. */
	missing?: string[],
};

/**  The text to preview some faces with, for one sample text. */
export type SampleTextRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  The sample text the user chose. */
	text: string,
};

/**  Start a scan. Returns at once; progress arrives as `Event::ScanProgress`. */
export type ScanRequest = {
	/**  One source, or every source when absent. */
	source?: SourceId | null,
};

/**  A search. An empty query with filters lists everything that passes them. */
export type SearchRequest = {
	/**
	 *  Free text over family, style, PostScript name, foundry, designer, tags
	 *  and file name; typo-tolerant; style words ("bold italic") narrow styles.
	 */
	query?: string,
	/**  Filters. */
	filters?: Filters,
	/**  Window over the family groups. */
	page?: Page,
};

/**  Search results grouped by family. */
export type SearchResponse = {
	/**  Family groups in this page. */
	families: FamilyHit[],
	/**  Family groups in all pages. */
	total: number,
	/**  The result count of every filter value. */
	counts?: FilterCounts | null,
};

/**
 *  One font of an exported set, referenced by content so a teammate's copy
 *  at another path still matches.
 */
export type SetEntry = {
	/**  Family name. */
	family: string,
	/**  Style name. */
	style: string,
	/**  blake3 hash of the file, hex. */
	hash: string,
};

/**  A project set as portable JSON (no files). */
export type SetExport = {
	/**  Set name. */
	name: string,
	/**  Its fonts. */
	fonts: SetEntry[],
};

/**  A project set: fonts activated together. */
export type SetId = number;

/**  Pause or resume a source. */
export type SetSourcePausedRequest = {
	/**  The source. */
	source: SourceId,
	/**  Paused (hidden) or not. */
	paused: boolean,
};

/**
 *  The user's settings. Missing keys take their defaults.
 * 
 *  The TypeScript type marks every field optional because of the defaults;
 *  a response always carries all of them.
 */
export type Settings = {
	/**  What the Activate button does. */
	activationMode?: ActivationMode,
	/**  What activation does when a face clashes with another font. */
	onConflict?: ConflictPolicy,
	/**  Light, dark or the OS appearance. */
	theme?: Theme,
	/**  Comfortable or compact lists. */
	density?: Density,
	/**  The largest size of the preview cache, in megabytes (64–16384). */
	cacheLimitMb?: number,
	/**
	 *  Minutes between automatic rescans of the sources; 0 turns them off
	 *  (at most 1440, one day).
	 */
	rescanIntervalMinutes?: number,
};

/**  Change some settings; absent fields keep their value. */
export type SettingsUpdate = {
	/**  What the Activate button does. */
	activationMode?: ActivationMode | null,
	/**  What activation does when a face clashes with another font. */
	onConflict?: ConflictPolicy | null,
	/**  Light, dark or the OS appearance. */
	theme?: Theme | null,
	/**  Comfortable or compact lists. */
	density?: Density | null,
	/**  The largest size of the preview cache, in megabytes. */
	cacheLimitMb?: number | null,
	/**  Minutes between automatic rescans; 0 turns them off. */
	rescanIntervalMinutes?: number | null,
};

/**  The shortlist for a brief. */
export type Shortlist = {
	/**  Best first. */
	candidates: Candidate[],
};

/**  A similar face and why. */
export type SimilarFace = {
	/**  The face. */
	face: FaceSummary,
	/**  0.0–1.0; higher is closer. */
	score: number | null,
	/**  Plain-word reasons ("matching x-height"). */
	reasons: string[],
};

/**  Faces that look like this one. */
export type SimilarRequest = {
	/**  The face to compare against. */
	face: FaceId,
	/**  Results to return. */
	limit: number,
};

/**  Upright, italic or oblique. */
export type Slant = 
/**  Upright. */
"upright" | 
/**  Italic. */
"italic" | 
/**  Oblique (slanted roman). */
"oblique";

/**  A source of fonts. */
export type Source = {
	/**  Id. */
	id: SourceId,
	/**  Absolute folder path. */
	path: string,
	/**  What kind of source. */
	kind: SourceKind,
	/**  Hidden from the library without being removed. */
	paused: boolean,
	/**  Faces indexed from it. */
	faceCount: number,
};

/**  A watched folder, the system fonts, or the library folder. */
export type SourceId = number;

/**  Where a source's fonts come from. */
export type SourceKind = 
/**  A folder the user chose; indexed in place. */
"watched" | 
/**  The OS font folders; read-only, never deactivated by the app. */
"system" | 
/**  The user-chosen folder that "Copy to library folder" imports into. */
"libraryFolder";

/**  One style on a family's weight line. */
export type StyleMark = {
	/**  `OS/2.usWeightClass` (100–1000). */
	weight: number,
	/**  Italic or oblique. */
	italic: boolean,
};

/**  Which characters to keep when subsetting. */
export type Subset = 
/**  Named presets (`latin`, `latin-ext`, `cyrillic`, `greek`, `vietnamese`). */
{ kind: "presets"; 
/**  Preset names. */
names: string[] } | 
/**  CSS `unicode-range` values (`U+0000-00FF`). */
{ kind: "unicode"; 
/**  Ranges. */
ranges: string[] } | 
/**  Every character of a sample text. */
{ kind: "text"; 
/**  The text. */
text: string };

/**  Characters a font must cover. */
export type Supports = 
/**  Every listed language preset (AND), by code (`sr-Cyrl`, `pl`). */
{ kind: "languages"; 
/**  Preset codes from `list_languages`. */
codes: string[] } | 
/**  Every character of a pasted text. */
{ kind: "text"; 
/**  The text. */
text: string };

/**  A tag. */
export type Tag = {
	/**  Id. */
	id: TagId,
	/**  Name. */
	name: string,
	/**  Faces carrying it. */
	faceCount: number,
};

/**  Attach tags to faces; tags that do not exist yet are created. */
export type TagFacesRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  Tag names. */
	tags: string[],
};

/**  A free-form tag. */
export type TagId = number;

/**  What to act on. */
export type Target = 
/**  These faces. */
{ kind: "faces"; 
/**  Face ids. */
faces: FaceId[] } | 
/**  Every face of a family. */
{ kind: "family"; 
/**  Family id. */
family: FamilyId } | 
/**  Every face in a collection. */
{ kind: "collection"; 
/**  Collection id. */
collection: CollectionId } | 
/**  Every face in a project set. */
{ kind: "set"; 
/**  Set id. */
set: SetId };

/**  The colors of the app. */
export type Theme = 
/**  Follow the OS appearance. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

/**  Detach tags from faces. */
export type UntagFacesRequest = {
	/**  The faces. */
	faces: FaceId[],
	/**  The tags. */
	tags: TagId[],
};

/**  Change user metadata on faces; absent fields are left as they are. */
export type UserMetaUpdate = {
	/**  The faces. */
	faces: FaceId[],
	/**  Favorite or not. */
	favorite?: boolean | null,
	/**  1–5 stars; 0 clears the rating. */
	rating?: number | null,
	/**  Notes; an empty string clears them. */
	notes?: string | null,
};

/**  A web font format. */
export type WebFormat = 
/**  WOFF 2. */
"woff2" | 
/**  WOFF 1. */
"woff";

/**  An inclusive weight range (100–1000). */
export type WeightRange = {
	/**  Lowest weight. */
	min: number,
	/**  Highest weight. */
	max: number,
};

/**  An inclusive OS/2 width-class range (1 ultra-condensed – 9 ultra-expanded). */
export type WidthRange = {
	/**  Narrowest width class. */
	min: number,
	/**  Widest width class. */
	max: number,
};

export const API_VERSION: ApiVersion = { major: 0, minor: 6, patch: 0 };
